from pathlib import Path
files=['H5Dfill.c','H5Gdense.c','H5Oshared.c','H5Adense.c','H5Tbit.c','H5Gtraverse.c']
for fn in files:
 p=Path('/workspace/repo-vul/src-vul/hdf5/src')/fn
 lines=p.read_text(errors='ignore').splitlines()
 print('\n====',fn)
 for i,l in enumerate(lines,1):
  if 'H5WB_wrap' in l or 'H5WB_actual' in l:
   s=max(1,i-25); e=min(len(lines),i+35)
   print(f'-- around {i}')
   for j in range(s,e+1): print(f'{j:5d} {lines[j-1]}')
   print()
